export function rangeWeight(hand,type){const a=ranks.indexOf(hand[0]),b=ranks.indexOf(hand[1]),s=hand.endsWith('s'),pair=a===b;if(type==='utg'||type==='btn')return yokosawaAction(hand,{behind:type==='utg'?5:2,ante:false})==='raise'?1:0;if(type==='call'){const prior=rangeWeight(hand,'bb');return prior*(pair?(a===7?1:.35):a===0?1:a===1?.85:b===7?.55:s&&['QJ','QT','JT'].includes(hand.slice(0,2))?.4:0)}const action=yokosawaAction(hand,{openerBehind:2,bb:true,ante:false});return action==='fold'?0:action==='raise'?.25:1;}


